pragma solidity ^0.8.0;

import {Ownable} from "solady/auth/Ownable.sol";

import {ERC20} from "solmate/tokens/ERC20.sol";

import {BaseV2Gauge} from "@gauges/BaseV2Gauge.sol";

import {FlywheelBoosterGaugeWeight} from "@rewards/booster/FlywheelBoosterGaugeWeight.sol";
import {FlywheelBribeRewards} from "@rewards/rewards/FlywheelBribeRewards.sol";
import {FlywheelCore} from "@rewards/FlywheelCoreStrategy.sol";

import {BaseV2GaugeFactory, BaseV2GaugeManager} from "./BaseV2GaugeManager.sol";
import {IBribesFactory} from "../interfaces/IBribesFactory.sol";

/// @title Gauge Bribes Factory
contract BribesFactory is Ownable, IBribesFactory {
    /*///////////////////////////////////////////////////////////////
                        BRIBES FACTORY STATE
    //////////////////////////////////////////////////////////////*/

    /// @inheritdoc IBribesFactory
    uint256 public immutable rewardsCycleLength;

    FlywheelBoosterGaugeWeight private immutable flywheelGaugeWeightBooster;

    /// @inheritdoc IBribesFactory
    FlywheelCore[] public bribeFlywheels;

    /// @inheritdoc IBribesFactory
    mapping(FlywheelCore => uint256) public bribeFlywheelIds;

    /// @inheritdoc IBribesFactory
    mapping(FlywheelCore => bool) public activeBribeFlywheels;

    /// @inheritdoc IBribesFactory
    mapping(address => FlywheelCore) public flywheelTokens;

    /// @inheritdoc IBribesFactory
    BaseV2GaugeManager public immutable gaugeManager;

    /**
     * @notice Creates a new bribes factory
     * @param _gaugeManager Gauge Factory manager
     * @param _flywheelGaugeWeightBooster Flywheel Gauge Weight Booster
     * @param _rewardsCycleLength Rewards Cycle Length
     * @param _owner Owner of this contract
     */
    constructor(
        BaseV2GaugeManager _gaugeManager,
        FlywheelBoosterGaugeWeight _flywheelGaugeWeightBooster,
        uint256 _rewardsCycleLength,
        address _owner
    ) {
        _initializeOwner(_owner);
        gaugeManager = _gaugeManager;
        flywheelGaugeWeightBooster = _flywheelGaugeWeightBooster;
        rewardsCycleLength = _rewardsCycleLength;
    }

    /// @inheritdoc IBribesFactory
    function getBribeFlywheels() external view returns (FlywheelCore[] memory) {
        return bribeFlywheels;
    }

    /*//////////////////////////////////////////////////////////////
                        CREATE BRIBE LOGIC
    //////////////////////////////////////////////////////////////*/

    /// @inheritdoc IBribesFactory
    function addGaugetoFlywheel(address gauge, address bribeToken) external onlyGaugeFactory {
        if (address(flywheelTokens[bribeToken]) == address(0)) createBribeFlywheel(bribeToken);

        flywheelTokens[bribeToken].addStrategyForRewards(ERC20(gauge));
    }

    /// @inheritdoc IBribesFactory
    function createBribeFlywheel(address bribeToken) public {
        if (address(flywheelTokens[bribeToken]) != address(0)) revert BribeFlywheelAlreadyExists();

        FlywheelCore flywheel = new FlywheelCore(
            bribeToken,
            FlywheelBribeRewards(address(0)),
            flywheelGaugeWeightBooster,
            address(this)
        );

        flywheelTokens[bribeToken] = flywheel;

        uint256 id = bribeFlywheels.length;
        bribeFlywheels.push(flywheel);
        bribeFlywheelIds[flywheel] = id;
        activeBribeFlywheels[flywheel] = true;

        flywheel.setFlywheelRewards(address(new FlywheelBribeRewards(flywheel, rewardsCycleLength)));

        emit BribeFlywheelCreated(bribeToken, flywheel);
    }

    /*//////////////////////////////////////////////////////////////
                            MODIFIERS
    //////////////////////////////////////////////////////////////*/

    modifier onlyGaugeFactory() {
        if (!gaugeManager.activeGaugeFactories(BaseV2GaugeFactory(msg.sender))) {
            revert Unauthorized();
        }
        _;
    }
}
"},"src/gauges/factories/UniswapV3GaugeFactory.sol":{"content":"// SPDX-License-Identifier: MIT

pragma solidity ^0.8.0;

import {Ownable} from "solady/auth/Ownable.sol";

import {ERC20} from "solmate/tokens/ERC20.sol";

import {bHermesBoost} from "@hermes/tokens/bHermesBoost.sol";

import {UniswapV3Gauge, BaseV2Gauge} from "@gauges/UniswapV3Gauge.sol";

import {FlywheelGaugeRewards} from "@rewards/rewards/FlywheelGaugeRewards.sol";

import {
    UniswapV3Staker,
    IUniswapV3Factory,
    INonfungiblePositionManager,
    IUniswapV3Pool
} from "@v3-staker/UniswapV3Staker.sol";

import {BribesFactory} from "./BribesFactory.sol";
import {BaseV2GaugeFactory} from "./BaseV2GaugeFactory.sol";
import {BaseV2GaugeManager} from "./BaseV2GaugeManager.sol";

import {IUniswapV3GaugeFactory} from "../interfaces/IUniswapV3GaugeFactory.sol";

/// @title Uniswap V3 Gauge Factory
contract UniswapV3GaugeFactory is BaseV2GaugeFactory, IUniswapV3GaugeFactory {
    /*//////////////////////////////////////////////////////////////
                         FACTORY STATE
    //////////////////////////////////////////////////////////////*/

    /// @inheritdoc IUniswapV3GaugeFactory
    UniswapV3Staker public immutable override uniswapV3Staker;

    /// @inheritdoc IUniswapV3GaugeFactory
    FlywheelGaugeRewards public immutable override flywheelGaugeRewards;

    /**
     * @notice Creates a new Uniswap V3 Gauge Factory
     * @param _gaugeManager Gauge Factory manager
     * @param _bHermesBoost bHermes Boost Token
     * @param _factory Uniswap V3 Factory
     * @param _nonfungiblePositionManager Uniswap V3 Nonfungible Position Manager
     * @param _flywheelGaugeRewards Flywheel Gauge Rewards
     * @param _bribesFactory Bribes Factory
     * @param _owner Owner of this contract
     */
    constructor(
        BaseV2GaugeManager _gaugeManager,
        bHermesBoost _bHermesBoost,
        IUniswapV3Factory _factory,
        INonfungiblePositionManager _nonfungiblePositionManager,
        FlywheelGaugeRewards _flywheelGaugeRewards,
        BribesFactory _bribesFactory,
        address _owner
    ) BaseV2GaugeFactory(_gaugeManager, _bHermesBoost, _bribesFactory, _owner) {
        flywheelGaugeRewards = _flywheelGaugeRewards;
        uniswapV3Staker = new UniswapV3Staker(
            _factory,
            _nonfungiblePositionManager,
            this,
            _bHermesBoost,
            52 weeks,
            address(_flywheelGaugeRewards.minter()),
            address(_flywheelGaugeRewards.rewardToken())
        );
    }

    /*//////////////////////////////////////////////////////////////
                         GAUGE LOGIC
    //////////////////////////////////////////////////////////////*/

    /// @notice Creates a new Uniswap V3 Gauge
    function newGauge(address strategy, bytes memory data) internal override returns (BaseV2Gauge) {
        uint24 minimumWidth = abi.decode(data, (uint24));
        return new UniswapV3Gauge(
                flywheelGaugeRewards,
                address(uniswapV3Staker),
                strategy,
                minimumWidth,
                address(this)
            );
    }

    /// @notice Adds Gauge to UniswapV3Staker
    /// @dev Updates the UniswapV3 staker with bribe and minimum width information
    function afterCreateGauge(address strategy, bytes memory) internal override {
        uniswapV3Staker.updateGauges(IUniswapV3Pool(strategy));
    }

    /*//////////////////////////////////////////////////////////////
                         ADMIN LOGIC
    //////////////////////////////////////////////////////////////*/

    /// @inheritdoc IUniswapV3GaugeFactory
    function setMinimumWidth(address gauge, uint24 minimumWidth) external onlyOwner {
        if (!activeGauges[BaseV2Gauge(gauge)]) revert InvalidGauge();
        UniswapV3Gauge(gauge).setMinimumWidth(minimumWidth);
        uniswapV3Staker.updateGauges(IUniswapV3Pool(UniswapV3Gauge(gauge).strategy()));
    }
}
