/// @title Flywheel Instant Rewards.
contract FlywheelInstantRewards is BaseFlywheelRewards, IFlywheelInstantRewards {
    using SafeTransferLib for ERC20;
    using SafeCastLib for uint256;

    /// @notice RewardsDepot for this contract, shared between all strategy
    SingleRewardsDepot public immutable rewardsDepot;

    /**
     * @notice Flywheel Instant Rewards constructor.
     *  @param _flywheel flywheel core contract
     */
    constructor(FlywheelCore _flywheel) BaseFlywheelRewards(_flywheel) {
        rewardsDepot = new SingleRewardsDepot(rewardToken);
    }

    /// @inheritdoc IFlywheelInstantRewards
    function getAccruedRewards() external override onlyFlywheel returns (uint256) {
        return rewardsDepot.getRewards(); // get exisiting rewards
    }
}
"},"src/talos/TalosManager.sol":{"content":"// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import {IUniswapV3Pool} from "@uniswap/v3-core/contracts/interfaces/IUniswapV3Pool.sol";

import {ITalosBaseStrategy} from "./interfaces/ITalosBaseStrategy.sol";
import {ITalosManager} from "./interfaces/ITalosManager.sol";
import {ITalosOptimizer} from "./interfaces/ITalosOptimizer.sol";
import {PoolVariables} from "./libraries/PoolVariables.sol";

import {ITalosManager, AutomationCompatibleInterface} from "./interfaces/ITalosManager.sol";

/// @title Talos Strategy Manager - Manages rebalancing and reranging of Talos Positions
contract TalosManager is AutomationCompatibleInterface, ITalosManager {
    using PoolVariables for IUniswapV3Pool;

    /*//////////////////////////////////////////////////////////////
                        TALOS OPTIMIZER STATE
    //////////////////////////////////////////////////////////////*/

    /// @inheritdoc ITalosManager
    int24 public immutable ticksFromLowerRebalance;

    /// @inheritdoc ITalosManager
    int24 public immutable ticksFromUpperRebalance;

    /// @inheritdoc ITalosManager
    int24 public immutable ticksFromLowerRerange;

    /// @inheritdoc ITalosManager
    int24 public immutable ticksFromUpperRerange;

    /// @inheritdoc ITalosManager
    ITalosBaseStrategy public immutable strategy;

    /**
     * @notice Construct a new Talos Strategy Manager contract.
     * @param _strategy Strategy to manage.
     * @param _ticksFromLowerRebalance Ticks from lower tick to rebalance.
     * @param _ticksFromUpperRebalance Ticks from upper tick to rebalance.
     * @param _ticksFromLowerRerange Ticks from lower tick to rerange.
     * @param _ticksFromUpperRerange Ticks from upper tick to rerange.
     */
    constructor(
        address _strategy,
        int24 _ticksFromLowerRebalance,
        int24 _ticksFromUpperRebalance,
        int24 _ticksFromLowerRerange,
        int24 _ticksFromUpperRerange
    ) {
        strategy = ITalosBaseStrategy(_strategy);
        ticksFromLowerRebalance = _ticksFromLowerRebalance;
        ticksFromUpperRebalance = _ticksFromUpperRebalance;
        ticksFromLowerRerange = _ticksFromLowerRerange;
        ticksFromUpperRerange = _ticksFromUpperRerange;
    }

    /*//////////////////////////////////////////////////////////////
                        UPKEEP ACTION CHECKERS
    //////////////////////////////////////////////////////////////*/

    /**
     * @notice Returns true if strategy needs to be rebalanced
     * @dev Checks if current tick is in range, returns true if not
     */
    function getRebalance(ITalosBaseStrategy position) private view returns (bool) {
        //Calculate base ticks.
        (, int24 currentTick,,,,,) = position.pool().slot0();

        return currentTick - position.tickLower() >= ticksFromLowerRebalance
            || position.tickUpper() - currentTick >= ticksFromUpperRebalance;
    }

    /**
     * @notice Returns true if strategy needs to be reranged
     * @dev Checks if current tick is in range, returns true if not
     */
    function getRerange(ITalosBaseStrategy position) private view returns (bool) {
        //Calculate base ticks.
        (, int24 currentTick,,,,,) = position.pool().slot0();

        return currentTick - position.tickLower() >= ticksFromLowerRerange
            || position.tickUpper() - currentTick >= ticksFromUpperRerange;
    }

    /*//////////////////////////////////////////////////////////////
                            AUTOMATION
    //////////////////////////////////////////////////////////////*/

    /// @inheritdoc AutomationCompatibleInterface
    function checkUpkeep(bytes calldata) external view override returns (bool upkeepNeeded, bytes memory performData) {
        ITalosOptimizer optimizer = strategy.optimizer();

        // checks if price has not moved a lot recently.
        // This mitigates price manipulation during rebalance and also prevents placing orders when it's too volatile.
        try strategy.pool().checkDeviation(optimizer.maxTwapDeviation(), optimizer.twapDuration()) {}
        catch {
            return (false, "");
        }

        if (getRebalance(strategy)) {
            upkeepNeeded = true;
        } else if (getRerange(strategy)) {
            upkeepNeeded = true;
        }

        performData = "";
    }

    /// @inheritdoc AutomationCompatibleInterface
    /// @notice Rebalances or Reranges an Optimizer's positions.
    function performUpkeep(bytes calldata) external override {
        if (getRebalance(strategy)) {
            /**
             * @dev Swaps imbalanced token. Finds base position and limit position for imbalanced token if
             * we don't have balance during swap because of price impact.
             * mints all amounts to this position(including earned fees)
             */
            strategy.rebalance();
        } else if (getRerange(strategy)) {
            /**
             * @dev Finds base position and limit position for imbalanced token
             * mints all amounts to this position(including earned fees)
             */
            strategy.rerange();
        }
    }
}
"},"src/talos/TalosOptimizer.sol":{"content":"// SPDX-License-Identifier: MIT
// Logic inspired by Popsicle Finance Contracts (PopsicleV3Optimizer/contracts/popsicle-v3-optimizer/OptimizerStrategy.sol)
pragma solidity ^0.8.0;

import {Ownable} from "solady/auth/Ownable.sol";

import {ITalosOptimizer} from "./interfaces/ITalosOptimizer.sol";

/// @title Talos Optimizer - Manages optimization variables for Talos Positions
contract TalosOptimizer is Ownable, ITalosOptimizer {
    /*//////////////////////////////////////////////////////////////
                        TALOS OPTIMIZER STATE
    //////////////////////////////////////////////////////////////*/

    /// @inheritdoc ITalosOptimizer
    uint256 public override maxTotalSupply;
    /// @inheritdoc ITalosOptimizer
    uint32 public override twapDuration;
    /// @inheritdoc ITalosOptimizer
    int24 public override maxTwapDeviation;
    /// @inheritdoc ITalosOptimizer
    int24 public override tickRangeMultiplier;
    /// @inheritdoc ITalosOptimizer
    uint24 public override priceImpactPercentage;

    /**
     * @notice Constructor for Optimizer
     * @param _twapDuration TWAP duration in seconds for rebalance check
     * @param _maxTwapDeviation Max deviation from TWAP during rebalance
     * @param _tickRangeMultiplier Used to determine base order range
     * @param _priceImpactPercentage The price impact percentage during swap in hundredths of a bip, i.e. 1e-6
     * @param _maxTotalSupply Maximum TLP value that could be minted
     */
    constructor(
        uint32 _twapDuration,
        int24 _maxTwapDeviation,
        int24 _tickRangeMultiplier,
        uint24 _priceImpactPercentage,
        uint256 _maxTotalSupply,
        address _owner
    ) {
        if (_maxTwapDeviation < 20) revert MaxTwapDeviationTooLow();
        if (_twapDuration < 100) revert TwapDurationTooLow();
        if (_priceImpactPercentage >= 1e6 || _priceImpactPercentage == 0) {
            revert PriceImpactPercentageInvalid();
        }
        if (_maxTotalSupply == 0) revert MaxTotalSupplyIsZero();

        _initializeOwner(_owner);
        twapDuration = _twapDuration;
        maxTwapDeviation = _maxTwapDeviation;
        tickRangeMultiplier = _tickRangeMultiplier;
        priceImpactPercentage = _priceImpactPercentage;
        maxTotalSupply = _maxTotalSupply;
    }

    /*//////////////////////////////////////////////////////////////
                            ADMIN FUNCTIONS
    //////////////////////////////////////////////////////////////*/

    /// @inheritdoc ITalosOptimizer
    function setMaxTotalSupply(uint256 _maxTotalSupply) external onlyOwner {
        if (_maxTotalSupply == 0) revert MaxTotalSupplyIsZero();
        maxTotalSupply = _maxTotalSupply;
    }

    /// @inheritdoc ITalosOptimizer
    function setTwapDuration(uint32 _twapDuration) external onlyOwner {
        if (_twapDuration < 100) revert TwapDurationTooLow();
        twapDuration = _twapDuration;
    }

    /// @inheritdoc ITalosOptimizer
    function setMaxTwapDeviation(int24 _maxTwapDeviation) external onlyOwner {
        if (_maxTwapDeviation < 20) revert MaxTwapDeviationTooLow();
        maxTwapDeviation = _maxTwapDeviation;
    }

    /// @inheritdoc ITalosOptimizer
    function setTickRange(int24 _tickRangeMultiplier) external onlyOwner {
        tickRangeMultiplier = _tickRangeMultiplier;
    }

    /// @inheritdoc ITalosOptimizer
    function setPriceImpact(uint24 _priceImpactPercentage) external onlyOwner {
        if (_priceImpactPercentage >= 1e6 || _priceImpactPercentage == 0) {
            revert PriceImpactPercentageInvalid();
        }
        priceImpactPercentage = _priceImpactPercentage;
    }
}
"},"src/talos/TalosStrategyStaked.sol":{"content":"// SPDX-License-Identifier: MIT
pragma solidity >=0.8.0;

import {ERC20} from "solmate/tokens/ERC20.sol";

import {IUniswapV3Pool} from "@uniswap/v3-core/contracts/interfaces/IUniswapV3Pool.sol";
import {INonfungiblePositionManager} from "@uniswap/v3-periphery/contracts/interfaces/INonfungiblePositionManager.sol";

import {FlywheelCoreInstant} from "@rewards/FlywheelCoreInstant.sol";
import {MultiRewardsDepot} from "@rewards/depots/MultiRewardsDepot.sol";
import {FlywheelInstantRewards} from "@rewards/rewards/FlywheelInstantRewards.sol";

import {BoostAggregator} from "./boost-aggregator/BoostAggregator.sol";
import {TalosStrategySimple, TalosBaseStrategy} from "./strategies/TalosStrategySimple.sol";

import {ITalosOptimizer} from "./interfaces/ITalosOptimizer.sol";
import {ITalosStrategyStaked} from "./interfaces/ITalosStrategyStaked.sol";

library DeployStaked {
    function createTalosV3Strategy(
        IUniswapV3Pool pool,
        ITalosOptimizer optimizer,
        BoostAggregator boostAggregator,
        address strategyManager,
        FlywheelCoreInstant flywheel,
        address owner
    ) public returns (TalosBaseStrategy) {
        return new TalosStrategyStaked(
                pool,
                optimizer,
                boostAggregator,
                strategyManager,
                flywheel,
                owner
            );
    }
}

/// @title Tokenized Vault implementation for a staked Uniswap V3 Non-Fungible Positions.
contract TalosStrategyStaked is TalosStrategySimple, ITalosStrategyStaked {
    /*//////////////////////////////////////////////////////////////
                        TALOS STAKED STRATEGY STATE
    //////////////////////////////////////////////////////////////*/

    /// @inheritdoc ITalosStrategyStaked
    BoostAggregator public immutable override boostAggregator;

    /// @notice flywheel core responsible for assigning strategy rewards to its respective users.
    FlywheelCoreInstant public immutable flywheel;

    /// @notice staking flag indicating if the NFT is staked or not.
    bool private stakeFlag = false;

    /**
     * @notice Construct a new Talos Strategy Staked contract.
     * @param _pool Uniswap V3 Pool to manage.
     * @param _optimizer Talos Optimizer to use.
     * @param _boostAggregator BoostAggregator to stake NFTs in Uniswap V3 Staker
     * @param _strategyManager Strategy manager to use.
     * @param _flywheel flywheel core responsible for assigning strategy rewards to its respective users.
     * @param _owner Owner of the contract.
     */
    constructor(
        IUniswapV3Pool _pool,
        ITalosOptimizer _optimizer,
        BoostAggregator _boostAggregator,
        address _strategyManager,
        FlywheelCoreInstant _flywheel,
        address _owner
    )
        TalosStrategySimple(
            _pool,
            _optimizer,
            _boostAggregator.nonfungiblePositionManager(),
            _strategyManager,
            _owner
        )
    {
        flywheel = _flywheel;

        boostAggregator = _boostAggregator;
        _boostAggregator.setOwnRewardsDepot(address(FlywheelInstantRewards(_flywheel.flywheelRewards()).rewardsDepot()));
    }

    /*//////////////////////////////////////////////////////////////
                          INTERNAL HOOKS LOGIC
    //////////////////////////////////////////////////////////////*/

    function transfer(address _to, uint256 _amount) public override returns (bool) {
        flywheel.accrue(ERC20(address(this)), msg.sender, _to);
        return super.transfer(_to, _amount);
    }

    function transferFrom(address _from, address _to, uint256 _amount) public override returns (bool) {
        flywheel.accrue(ERC20(address(this)), _from, _to);
        return super.transferFrom(_from, _to, _amount);
    }

    /// @notice Hook that is called before a position is redeemed.
    /// @dev Responsible for collecting and accruing user rewards
    function beforeRedeem(uint256 _tokenId, address _owner) internal override {
        _earnFees(_tokenId);
        flywheel.accrue(_owner);
    }

    /// @notice Hook that is called after a position is redeemed.
    /// @dev Responsible for staking the position in the UniswapV3Staker
    function afterRedeem(uint256 _tokenId) internal override {
        _stake(_tokenId);
    }

    /// @notice Hook that is called before a position is deposited.
    /// @dev Responsible for collecting and accruing user rewards
    function beforeDeposit(uint256 _tokenId, address _receiver) internal override {
        _earnFees(_tokenId);
        flywheel.accrue(_receiver);
    }

    /// @notice Hook that is called after a position is deposited.
    /// @dev Responsible for staking the position in the UniswapV3Staker
    function afterDeposit(uint256 _tokenId) internal override {
        _stake(_tokenId);
    }

    /// @notice Hook that is called before a position is reranged.
    /// @dev Responsible for collecting and accruing strategy rewards
    function beforeRerange(uint256 _tokenId) internal override {
        _earnFees(_tokenId);
        flywheel.accrue(msg.sender);
    }

    /// @notice Hook that is called after a position is reranged.
    /// @dev Responsible for staking the position in the UniswapV3Staker
    function afterRerange(uint256 _tokenId) internal override {
        _stake(_tokenId);
    }

    /// @notice Collects fees from the pool
    /// @param _tokenId where to collect fees from
    function _earnFees(uint256 _tokenId) internal {
        if (liquidity == 0) return; // can't unstake when liquidity is zero

        // If not staked, collect fees from the pool
        if (stakeFlag) {
            _unstake(_tokenId);
        } else {
            (uint256 collect0, uint256 collect1) = nonfungiblePositionManager.collect(
                INonfungiblePositionManager.CollectParams({
                    tokenId: _tokenId,
                    recipient: address(this),
                    amount0Max: type(uint128).max,
                    amount1Max: type(uint128).max
                })
            );

            // Calculate protocol's fees
            protocolFees0 += collect0;
            protocolFees1 += collect1;
        }
    }

    /// @notice Unstakes all tokens from a specific tokenId
    /// @param _tokenId where to unstake from
    function _unstake(uint256 _tokenId) internal {
        // Unstaked, withdraws and sends fees to the rewards depot
        boostAggregator.unstakeAndWithdraw(_tokenId);

        stakeFlag = false;
    }

    /// @notice Stakes a specific pre existing position
    /// @param _tokenId position that needs to be staked
    function _stake(uint256 _tokenId) internal {
        if (liquidity == 0) return; // can't stake when liquidity is zero

        // try catch in case this position is not authorized to stake or current incentive does not have rewards
        try nonfungiblePositionManager.safeTransferFrom(address(this), address(boostAggregator), _tokenId) {
            stakeFlag = true; // flag to store staking state to avoid failing to unstake when it is not staked
        } catch {}
    }
}
"},"src/talos/TalosStrategyVanilla.sol":{"content":"// SPDX-License-Identifier: MIT
// Logic inspired by Popsicle Finance Contracts (PopsicleV3Optimizer/contracts/popsicle-v3-optimizer/PopsicleV3Optimizer.sol)
pragma solidity >=0.8.0;

import {Ownable} from "solady/auth/Ownable.sol";
import {FixedPointMathLib} from "solady/utils/FixedPointMathLib.sol";

import {ERC20} from "solmate/tokens/ERC20.sol";

import {IUniswapV3Pool} from "@uniswap/v3-core/contracts/interfaces/IUniswapV3Pool.sol";

import {INonfungiblePositionManager} from "@uniswap/v3-periphery/contracts/interfaces/INonfungiblePositionManager.sol";

import {ITalosOptimizer} from "./interfaces/ITalosOptimizer.sol";
import {PoolVariables} from "./libraries/PoolVariables.sol";

import {TalosStrategySimple, TalosBaseStrategy} from "./strategies/TalosStrategySimple.sol";

/// @title Deploy Vanilla
/// @notice This library deploys talos vanilla strategies
library DeployVanilla {
    function createTalosV3Vanilla(
        IUniswapV3Pool pool,
        ITalosOptimizer optimizer,
        INonfungiblePositionManager nonfungiblePositionManager,
        address strategyManager,
        address owner
    ) public returns (TalosBaseStrategy) {
        return new TalosStrategyVanilla(
                pool,
                optimizer,
                nonfungiblePositionManager,
                strategyManager,
                owner
            );
    }
}

/// @notice Tokenized Vault implementation for Uniswap V3 Non Fungible Positions.
/// @author Maia DAO (https://github.com/Maia-DAO)
contract TalosStrategyVanilla is TalosStrategySimple {
    using FixedPointMathLib for uint256;
    using FixedPointMathLib for uint128;
    using PoolVariables for IUniswapV3Pool;

    /// @notice The protocol's fee in hundredths of a bip, i.e. 1e-6
    uint24 private constant protocolFee = 2 * 1e5; //20%
    uint24 private constant GLOBAL_DIVISIONER = 1e6;

    /**
     * @notice Constructs a new TalosStrategyVanilla contract.
     * @param _pool The Uniswap V3 pool to manage.
     * @param _optimizer The optimizer contract to use.
     * @param _nonfungiblePositionManager The Uniswap V3 Non Fungible Position Manager contract.
     * @param _strategyManager The strategy manager contract.
     * @param _owner The owner of the contract.
     */
    constructor(
        IUniswapV3Pool _pool,
        ITalosOptimizer _optimizer,
        INonfungiblePositionManager _nonfungiblePositionManager,
        address _strategyManager,
        address _owner
    ) TalosStrategySimple(_pool, _optimizer, _nonfungiblePositionManager, _strategyManager, _owner) {}

    /*//////////////////////////////////////////////////////////////
                          INTERNAL HOOKS LOGIC
    //////////////////////////////////////////////////////////////*/

    /// @notice Performs the necessary actions before a withdraw can take place
    /// @param _tokenId position id that the user is trying to withdraw from
    function beforeRedeem(uint256 _tokenId, address) internal override {
        _earnFees(_tokenId);
        _compoundFees(_tokenId);
    }

    /// @notice Performs the necessary actions after a withdraw takes place
    /// @param _tokenId position id that the user is trying to withdraw from
    function afterRedeem(uint256 _tokenId) internal override {}

    /// @notice Performs the necessary actions before a deposit can take place
    /// @param _tokenId position id that the user wants to deposit in
    function beforeDeposit(uint256 _tokenId, address) internal override {
        _earnFees(_tokenId);
        _compoundFees(_tokenId);
    }

    /// @notice Performs the necessary actions after a deposit takes place
    /// @param _tokenId position id that the user wants to deposit in
    function afterDeposit(uint256 _tokenId) internal override {}

    /// @notice Performs the necessary actions before a re-range can take place
    /// @param _tokenId position id that the user wants to re-range
    function beforeRerange(uint256 _tokenId) internal override {
        _earnFees(_tokenId);
    }

    /// @notice Performs the necessary actions after a re-range takes place
    /// @param _tokenId position id that the user wants to deposit in
    function afterRerange(uint256 _tokenId) internal override {}

    /// @notice Collects fees from the pool to the protocol.
    /// @param _tokenId position id that the user wants to collect fees from
    function _earnFees(uint256 _tokenId) internal {
        if (liquidity == 0) return; // no fees to collect when liquidity is zero

        (uint256 collect0, uint256 collect1) = nonfungiblePositionManager.collect(
            INonfungiblePositionManager.CollectParams({
                tokenId: _tokenId,
                recipient: address(this),
                amount0Max: type(uint128).max,
                amount1Max: type(uint128).max
            })
        );

        uint24 _protocolFee = protocolFee;
        uint24 _GLOBAL_DIVISIONER = GLOBAL_DIVISIONER;

        // Calculate protocol's fees
        uint256 earnedProtocolFees0 = (collect0 * _protocolFee) / _GLOBAL_DIVISIONER;
        uint256 earnedProtocolFees1 = (collect1 * _protocolFee) / _GLOBAL_DIVISIONER;
        protocolFees0 += earnedProtocolFees0;
        protocolFees1 += earnedProtocolFees1;
        emit CollectFees(earnedProtocolFees0, earnedProtocolFees1, collect0, collect1);
    }

    /// @notice Compounds fees from the pool from a user prespective
    /// @param _tokenId position id that the user wants to compound fees from
    function _compoundFees(uint256 _tokenId) internal returns (uint256 amount0, uint256 amount1) {
        uint256 balance0 = token0.balanceOf(address(this)) - protocolFees0;
        uint256 balance1 = token1.balanceOf(address(this)) - protocolFees1;

        emit Snapshot(balance0, balance1);

        //Get Liquidity for Optimizer's balances
        uint128 _liquidity = pool.liquidityForAmounts(balance0, balance1, tickLower, tickUpper);

        // Add liquidity to the pool
        if (_liquidity > 0) {
            uint128 liquidityDifference;
            (liquidityDifference, amount0, amount1) = nonfungiblePositionManager.increaseLiquidity(
                INonfungiblePositionManager.IncreaseLiquidityParams({
                    tokenId: _tokenId,
                    amount0Desired: balance0,
                    amount1Desired: balance1,
                    amount0Min: 0,
                    amount1Min: 0,
                    deadline: block.timestamp
                })
            );
            liquidity += liquidityDifference;
            emit CompoundFees(amount0, amount1);
        }
    }

    /*//////////////////////////////////////////////////////////////
                                EVENTS
    //////////////////////////////////////////////////////////////*/

    /// @notice Emitted when fees was collected from the pool
    /// @param feesFromPool0 Total amount of fees collected in terms of token 0
    /// @param feesFromPool1 Total amount of fees collected in terms of token 1
    /// @param usersFees0 Total amount of fees collected by users in terms of token 0
    /// @param usersFees1 Total amount of fees collected by users in terms of token 1
    event CollectFees(uint256 feesFromPool0, uint256 feesFromPool1, uint256 usersFees0, uint256 usersFees1);

    /// @notice Emitted when fees was compuonded to the pool
    /// @param amount0 Total amount of fees compounded in terms of token 0
    /// @param amount1 Total amount of fees compounded in terms of token 1
    event CompoundFees(uint256 amount0, uint256 amount1);
}
"},"src/talos/base/TalosBaseStrategy.sol":{"content":"// SPDX-License-Identifier: MIT
// Logic inspired by Popsicle Finance Contracts (PopsicleV3Optimizer/contracts/popsicle-v3-optimizer/PopsicleV3Optimizer.sol)
pragma solidity >=0.8.0;

import {Ownable} from "solady/auth/Ownable.sol";
import {SafeCastLib} from "solady/utils/SafeCastLib.sol";
import {SafeTransferLib} from "solady/utils/SafeTransferLib.sol";
import {FixedPointMathLib} from "solady/utils/FixedPointMathLib.sol";

import {ReentrancyGuard} from "solmate/utils/ReentrancyGuard.sol";
import {ERC20} from "solmate/tokens/ERC20.sol";

import {IERC721Receiver} from "@openzeppelin/contracts/token/ERC721/IERC721Receiver.sol";

import {IUniswapV3Pool} from "@uniswap/v3-core/contracts/interfaces/IUniswapV3Pool.sol";
import {INonfungiblePositionManager} from "@uniswap/v3-periphery/contracts/interfaces/INonfungiblePositionManager.sol";

import {PoolVariables} from "../libraries/PoolVariables.sol";

import {ITalosBaseStrategy} from "../interfaces/ITalosBaseStrategy.sol";
import {ITalosOptimizer} from "../interfaces/ITalosOptimizer.sol";

/// @title Tokenized Vault implementation for Uniswap V3 Non Fungible Positions.
abstract contract TalosBaseStrategy is Ownable, ERC20, ReentrancyGuard, ITalosBaseStrategy {
    using SafeTransferLib for address;
    using FixedPointMathLib for uint256;
    using FixedPointMathLib for uint128;
    using SafeCastLib for uint256;
    using SafeCastLib for uint128;
    using PoolVariables for IUniswapV3Pool;

    /*//////////////////////////////////////////////////////////////
                        TALOS BASE STRATEGY STATE
    //////////////////////////////////////////////////////////////*/

    /// @inheritdoc ITalosBaseStrategy
    uint256 public override tokenId;
    /// @inheritdoc ITalosBaseStrategy
    uint128 public override liquidity;

    /// @inheritdoc ITalosBaseStrategy
    uint256 public protocolFees0;
    /// @inheritdoc ITalosBaseStrategy
    uint256 public protocolFees1;

    /// @notice Current tick lower of Optimizer pool position
    /// @inheritdoc ITalosBaseStrategy
    int24 public override tickLower;
    /// @notice Current tick higher of Optimizer pool position
    /// @inheritdoc ITalosBaseStrategy
    int24 public override tickUpper;

    /// @inheritdoc ITalosBaseStrategy
    bool public initialized;

    /*//////////////////////////////////////////////////////////////
                               IMMUTABLES
    //////////////////////////////////////////////////////////////*/

    /// @inheritdoc ITalosBaseStrategy
    ERC20 public immutable override token0;
    /// @inheritdoc ITalosBaseStrategy
    ERC20 public immutable override token1;
    /// @inheritdoc ITalosBaseStrategy
    int24 public immutable override tickSpacing;
    /// @inheritdoc ITalosBaseStrategy
    uint24 public immutable override poolFee;
    /// @inheritdoc ITalosBaseStrategy
    IUniswapV3Pool public immutable override pool;
    /// @inheritdoc ITalosBaseStrategy
    ITalosOptimizer public immutable override optimizer;
    /// @inheritdoc ITalosBaseStrategy
    address public immutable strategyManager;
    /// @inheritdoc ITalosBaseStrategy
    INonfungiblePositionManager public immutable override nonfungiblePositionManager;

    uint24 internal constant MULTIPLIER = 1e6;

    constructor(
        IUniswapV3Pool _pool,
        ITalosOptimizer _optimizer,
        INonfungiblePositionManager _nonfungiblePositionManager,
        address _strategyManager,
        address _owner
    ) ERC20("TALOS LP", "TLP", 18) {
        _initializeOwner(_owner);
        optimizer = _optimizer;
        nonfungiblePositionManager = _nonfungiblePositionManager;
        strategyManager = _strategyManager;
        pool = _pool;
        token0 = ERC20(_pool.token0());
        token1 = ERC20(_pool.token1());
        tickSpacing = _pool.tickSpacing();
        poolFee = _pool.fee();
    }

    /*//////////////////////////////////////////////////////////////
                            INITIALIZATION
    //////////////////////////////////////////////////////////////*/

    /// @inheritdoc ITalosBaseStrategy
    function init(uint256 amount0Desired, uint256 amount1Desired, address receiver)
        external
        virtual
        nonReentrant
        returns (uint256 shares, uint256 amount0, uint256 amount1)
    {
        if (initialized) revert AlreadyInitialized();

        {
            // Own Scope to avoid stack to deep
            int24 _tickSpacing = tickSpacing; // Saves an extra SLOAD
            int24 baseThreshold = _tickSpacing * optimizer.tickRangeMultiplier();
            (, int24 currentTick,,,,,) = pool.slot0();
            int24 tickFloor = PoolVariables.floor(currentTick, _tickSpacing);

            int24 _tickLower = tickFloor - baseThreshold; // Saves an extra SLOAD
            int24 _tickUpper = tickFloor + baseThreshold; // Saves an extra SLOAD
            PoolVariables.checkRange(_tickLower, _tickUpper); // Check ticks also for overflow/underflow
            tickLower = _tickLower;
            tickUpper = _tickUpper;
        }

        (ERC20 _token0, ERC20 _token1) = (token0, token1);
        address(_token0).safeTransferFrom(msg.sender, address(this), amount0Desired);
        address(_token1).safeTransferFrom(msg.sender, address(this), amount1Desired);

        INonfungiblePositionManager _nonfungiblePositionManager = nonfungiblePositionManager; // Saves an extra SLOAD

        address(_token0).safeApprove(address(_nonfungiblePositionManager), type(uint256).max);
        address(_token1).safeApprove(address(_nonfungiblePositionManager), type(uint256).max);

        uint128 _liquidity;
        uint256 _tokenId;
        (_tokenId, _liquidity, amount0, amount1) = _nonfungiblePositionManager.mint(
            INonfungiblePositionManager.MintParams({
                token0: address(_token0),
                token1: address(_token1),
                fee: poolFee,
                tickLower: tickLower,
                tickUpper: tickUpper,
                amount0Desired: amount0Desired,
                amount1Desired: amount1Desired,
                amount0Min: 0,
                amount1Min: 0,
                recipient: address(this),
                deadline: block.timestamp
            })
        );

        if (amount0 == 0 && amount1 == 0) revert AmountsAreZero();

        shares = _liquidity * MULTIPLIER;
        liquidity = _liquidity;
        tokenId = _tokenId;

        _mint(receiver, shares);
        if (totalSupply > optimizer.maxTotalSupply()) revert ExceedingMaxTotalSupply();

        emit Initialize(tokenId, msg.sender, receiver, amount0, amount1, shares);

        afterDeposit(_tokenId);
        initialized = true;

        // Refund in both assets.
        if (amount0 < amount0Desired) {
            uint256 refund0 = amount0Desired - amount0;
            address(_token0).safeTransfer(msg.sender, refund0);
        }

        if (amount1 < amount1Desired) {
            uint256 refund1 = amount1Desired - amount1;
            address(_token1).safeTransfer(msg.sender, refund1);
        }
    }

    /*//////////////////////////////////////////////////////////////
                        DEPOSIT/WITHDRAWAL LOGIC
    //////////////////////////////////////////////////////////////*/

    /// @inheritdoc ITalosBaseStrategy
    function deposit(uint256 amount0Desired, uint256 amount1Desired, address receiver)
        public
        virtual
        override
        nonReentrant
        checkDeviation
        returns (uint256 shares, uint256 amount0, uint256 amount1)
    {
        uint256 _tokenId = tokenId;

        beforeDeposit(_tokenId, receiver);

        (ERC20 _token0, ERC20 _token1) = (token0, token1);

        address(_token0).safeTransferFrom(msg.sender, address(this), amount0Desired);
        address(_token1).safeTransferFrom(msg.sender, address(this), amount1Desired);

        uint128 liquidityDifference;

        (liquidityDifference, amount0, amount1) = nonfungiblePositionManager.increaseLiquidity(
            INonfungiblePositionManager.IncreaseLiquidityParams({
                tokenId: _tokenId,
                amount0Desired: amount0Desired,
                amount1Desired: amount1Desired,
                amount0Min: 0,
                amount1Min: 0,
                deadline: block.timestamp
            })
        );

        if (amount0 == 0 && amount1 == 0) revert AmountsAreZero();

        uint256 supply = totalSupply; // Saves an extra SLOAD if totalSupply is non-zero.
        shares = supply == 0 ? liquidityDifference * MULTIPLIER : (liquidityDifference * supply) / liquidity;
        liquidity += liquidityDifference;

        _mint(receiver, shares);
        if (totalSupply > optimizer.maxTotalSupply()) revert ExceedingMaxTotalSupply();

        emit Deposit(msg.sender, receiver, amount0, amount1, shares);

        afterDeposit(_tokenId);

        // Refund in both assets.
        if (amount0 < amount0Desired) {
            uint256 refund0 = amount0Desired - amount0;
            address(_token0).safeTransfer(msg.sender, refund0);
        }

        if (amount1 < amount1Desired) {
            uint256 refund1 = amount1Desired - amount1;
            address(_token1).safeTransfer(msg.sender, refund1);
        }
    }

    /// @inheritdoc ITalosBaseStrategy
    function redeem(uint256 shares, uint256 amount0Min, uint256 amount1Min, address receiver, address _owner)
        public
        virtual
        override
        nonReentrant
        checkDeviation
        returns (uint256 amount0, uint256 amount1)
    {
        if (msg.sender != _owner) {
            uint256 allowed = allowance[_owner][msg.sender]; // Saves gas for limited approvals.

            if (allowed != type(uint256).max) allowance[_owner][msg.sender] = allowed - shares;
        }

        if (shares == 0) revert RedeemingZeroShares();
        if (receiver == address(0)) revert ReceiverIsZeroAddress();

        uint256 _tokenId = tokenId;

        beforeRedeem(_tokenId, receiver);

        INonfungiblePositionManager _nonfungiblePositionManager = nonfungiblePositionManager; // Saves an extra SLOAD
        {
            uint128 liquidityToDecrease = uint128((liquidity * shares) / totalSupply);

            (amount0, amount1) = _nonfungiblePositionManager.decreaseLiquidity(
                INonfungiblePositionManager.DecreaseLiquidityParams({
                    tokenId: _tokenId,
                    liquidity: liquidityToDecrease,
                    amount0Min: amount0Min,
                    amount1Min: amount1Min,
                    deadline: block.timestamp
                })
            );

            if (amount0 == 0 && amount1 == 0) revert AmountsAreZero();

            _burn(_owner, shares);

            liquidity -= liquidityToDecrease;
        }
        emit Redeem(msg.sender, receiver, _owner, amount0, amount1, shares);

        (amount0, amount1) = _nonfungiblePositionManager.collect(
            INonfungiblePositionManager.CollectParams({
                tokenId: _tokenId,
                recipient: receiver,
                amount0Max: type(uint128).max,
                amount1Max: type(uint128).max
            })
        );

        afterRedeem(_tokenId);
    }

    /*//////////////////////////////////////////////////////////////
                        RERANGE/REBALANCE LOGIC
    //////////////////////////////////////////////////////////////*/

    /// @inheritdoc ITalosBaseStrategy
    function rerange() external virtual override nonReentrant checkDeviation onlyStrategyManager {
        uint256 _tokenId = tokenId;
        beforeRerange(_tokenId);
        // Redeem all liquidity from pool to rerange for Optimizer's balances.
        _withdrawAll(_tokenId);

        (uint256 amount0, uint256 amount1) = doRerange();
        emit Rerange(tokenId, tickLower, tickUpper, amount0, amount1);

        afterRerange(tokenId); // tokenId changed in doRerange
    }

    /// @inheritdoc ITalosBaseStrategy
    function rebalance() external virtual override nonReentrant checkDeviation onlyStrategyManager {
        uint256 _tokenId = tokenId;
        beforeRerange(_tokenId);
        // Redeem all liquidity from pool to rerange for Optimizer's balances.
        _withdrawAll(_tokenId);

        (uint256 amount0, uint256 amount1) = doRebalance();
        emit Rerange(tokenId, tickLower, tickUpper, amount0, amount1);

        afterRerange(tokenId); // tokenId changed in doRerange
    }

    /*//////////////////////////////////////////////////////////////
                            EXTERNAL HOOKS
    //////////////////////////////////////////////////////////////*/

    /// @inheritdoc IERC721Receiver
    function onERC721Received(address, address, uint256, bytes calldata) external pure override returns (bytes4) {
        return this.onERC721Received.selector;
    }

    /// @inheritdoc ITalosBaseStrategy
    function uniswapV3SwapCallback(int256 amount0, int256 amount1, bytes calldata _data) external {
        if (msg.sender != address(pool)) revert CallerIsNotPool();
        if (amount0 == 0 && amount1 == 0) revert AmountsAreZero();
        SwapCallbackData memory data = abi.decode(_data, (SwapCallbackData));
        bool zeroForOne = data.zeroForOne;

        if (zeroForOne) address(token0).safeTransfer(msg.sender, uint256(amount0));
        else address(token1).safeTransfer(msg.sender, uint256(amount1));
    }

    /*//////////////////////////////////////////////////////////////
                          INTERNAL HOOKS LOGIC
    //////////////////////////////////////////////////////////////*/

    /// @notice Redeems all liquidity for a specific tokenId
    /// @param _tokenId position to withdraw liquidity from
    function _withdrawAll(uint256 _tokenId) internal {
        uint128 _liquidity = liquidity; // Saves an extra SLOAD if totalSupply is non-zero.
        if (_liquidity == 0) return;
        INonfungiblePositionManager _nonfungiblePositionManager = nonfungiblePositionManager;
        _nonfungiblePositionManager.decreaseLiquidity(
            INonfungiblePositionManager.DecreaseLiquidityParams({
                tokenId: _tokenId,
                liquidity: _liquidity,
                amount0Min: 0,
                amount1Min: 0,
                deadline: block.timestamp
            })
        );
        liquidity = 0;
        _nonfungiblePositionManager.collect(
            INonfungiblePositionManager.CollectParams({
                tokenId: _tokenId,
                recipient: address(this),
                amount0Max: type(uint128).max,
                amount1Max: type(uint128).max
            })
        );
    }

    function beforeDeposit(uint256 _tokenId, address _receiver) internal virtual;

    function afterDeposit(uint256 _tokenId) internal virtual;

    function beforeRedeem(uint256 _tokenId, address _owner) internal virtual;

    function afterRedeem(uint256 _tokenId) internal virtual;

    function beforeRerange(uint256 _tokenId) internal virtual;

    function afterRerange(uint256 _tokenId) internal virtual;

    function doRerange() internal virtual returns (uint256 amount0, uint256 amount1);

    function doRebalance() internal virtual returns (uint256 amount0, uint256 amount1);

    /*//////////////////////////////////////////////////////////////
                            ADMIN FUNCTIONS
    //////////////////////////////////////////////////////////////*/

    /// @inheritdoc ITalosBaseStrategy
    function collectProtocolFees(uint256 amount0, uint256 amount1) external nonReentrant onlyOwner {
        uint256 _protocolFees0 = protocolFees0;
        uint256 _protocolFees1 = protocolFees1;

        if (amount0 > _protocolFees0) {
            revert Token0AmountIsBiggerThanProtocolFees();
        }
        if (amount1 > _protocolFees1) {
            revert Token1AmountIsBiggerThanProtocolFees();
        }
        ERC20 _token0 = token0;
        ERC20 _token1 = token1;
        uint256 balance0 = _token0.balanceOf(address(this));
        uint256 balance1 = _token1.balanceOf(address(this));
        require(balance0 >= amount0 && balance1 >= amount1);
        if (amount0 > 0) _token0.transfer(msg.sender, amount0);
        if (amount1 > 0) _token1.transfer(msg.sender, amount1);

        protocolFees0 = _protocolFees0 - amount0;
        protocolFees1 = _protocolFees1 - amount1;
        emit RewardPaid(msg.sender, amount0, amount1);
    }

    /*//////////////////////////////////////////////////////////////
                                MODIFIERS
    //////////////////////////////////////////////////////////////*/

    /// @notice Function modifier that checks if price has not moved a lot recently.
    /// This mitigates price manipulation during rebalance and also prevents placing orders when it's too volatile.
    modifier checkDeviation() {
        ITalosOptimizer _optimizer = optimizer;
        pool.checkDeviation(_optimizer.maxTwapDeviation(), _optimizer.twapDuration());
        _;
    }

    /// @notice Function modifier that checks if msg.sender is the strategy manager.
    modifier onlyStrategyManager() {
        if (msg.sender != strategyManager) revert NotStrategyManager();
        _;
    }
}
"},"src/talos/boost-aggregator/BoostAggregator.sol":{"content":"// SPDX-License-Identifier: MIT
pragma solidity >=0.8.0;

import {Ownable} from "solady/auth/Ownable.sol";
import {SafeTransferLib} from "solady/utils/SafeTransferLib.sol";

import {ERC20} from "solmate/tokens/ERC20.sol";

import {IERC721Receiver} from "@openzeppelin/contracts/token/ERC721/IERC721Receiver.sol";

import {INonfungiblePositionManager} from "@uniswap/v3-periphery/contracts/interfaces/INonfungiblePositionManager.sol";

import {bHermesBoost} from "@hermes/tokens/bHermesBoost.sol";
import {UniswapV3Staker} from "@v3-staker/UniswapV3Staker.sol";

import {IBoostAggregator} from "../interfaces/IBoostAggregator.sol";

/// @title Boost Aggregator for Uniswap V3 NFTs
contract BoostAggregator is Ownable, IBoostAggregator {
    using SafeTransferLib for address;

    /*//////////////////////////////////////////////////////////////
                        BOOST AGGREGATOR STATE
    //////////////////////////////////////////////////////////////*/

    /// @inheritdoc IBoostAggregator
    INonfungiblePositionManager public immutable nonfungiblePositionManager;

    /// @inheritdoc IBoostAggregator
    UniswapV3Staker public immutable uniswapV3Staker;

    /// @inheritdoc IBoostAggregator
    bHermesBoost public immutable hermesGaugeBoost;

    /// @inheritdoc IBoostAggregator
    ERC20 public immutable hermes;

    /// @inheritdoc IBoostAggregator
    mapping(address => address) public userToRewardsDepot;

    /// @inheritdoc IBoostAggregator
    mapping(uint256 => address) public tokenIdToUser;

    /// @inheritdoc IBoostAggregator
    mapping(uint256 => uint256) public tokenIdRewards;

    /// @inheritdoc IBoostAggregator
    mapping(address => bool) public whitelistedAddresses;

    /// @inheritdoc IBoostAggregator
    uint256 public protocolRewards;

    /// @inheritdoc IBoostAggregator
    uint256 public protocolFee = 2000; // 20%
    // divisioner for protocol fee
    uint256 private constant DIVISIONER = 10000;

    /**
     * @notice Creates a new BoostAggregator
     * @param _uniswapV3Staker The UniswapV3Staker contract
     * @param _hermes The hermes token contract
     * @param _owner The owner of this contract
     */
    constructor(UniswapV3Staker _uniswapV3Staker, ERC20 _hermes, address _owner) {
        _initializeOwner(_owner);
        uniswapV3Staker = _uniswapV3Staker;
        hermesGaugeBoost = uniswapV3Staker.hermesGaugeBoost();
        nonfungiblePositionManager = uniswapV3Staker.nonfungiblePositionManager();
        hermes = _hermes;
    }

    /*//////////////////////////////////////////////////////////////
                            EXTERNAL HOOKS
    //////////////////////////////////////////////////////////////*/

    /// @inheritdoc IERC721Receiver
    /// @dev msg.sender not validated to be nonfungiblePositionManager in order to allow
    ///      whitelisted addresses to retrieve NFTs incorrectly sent to this contract
    function onERC721Received(address, address from, uint256 tokenId, bytes calldata)
        external
        override
        onlyWhitelisted(from)
        returns (bytes4)
    {
        // update tokenIdRewards prior to staking
        tokenIdRewards[tokenId] = uniswapV3Staker.tokenIdRewards(tokenId);
        // map tokenId to user
        tokenIdToUser[tokenId] = from;
        // stake NFT to Uniswap V3 Staker
        nonfungiblePositionManager.safeTransferFrom(address(this), address(uniswapV3Staker), tokenId);

        return this.onERC721Received.selector;
    }

    /*//////////////////////////////////////////////////////////////
                        REWARD DEPOTS LOGIC
    //////////////////////////////////////////////////////////////*/

    /// @inheritdoc IBoostAggregator
    function setOwnRewardsDepot(address rewardsDepot) external {
        userToRewardsDepot[msg.sender] = rewardsDepot;
    }

    /*//////////////////////////////////////////////////////////////
                            UNSTAKE LOGIC
    //////////////////////////////////////////////////////////////*/

    /// @inheritdoc IBoostAggregator
    function unstakeAndWithdraw(uint256 tokenId) external {
        address user = tokenIdToUser[tokenId];
        if (user != msg.sender) revert NotTokenIdOwner();

        // unstake NFT from Uniswap V3 Staker
        uniswapV3Staker.unstakeToken(tokenId);

        uint256 pendingRewards = uniswapV3Staker.tokenIdRewards(tokenId) - tokenIdRewards[tokenId];

        if (pendingRewards > DIVISIONER) {
            uint256 newProtocolRewards = (pendingRewards * protocolFee) / DIVISIONER;
            /// @dev protocol rewards stay in stake contract
            protocolRewards += newProtocolRewards;
            pendingRewards -= newProtocolRewards;

            address rewardsDepot = userToRewardsDepot[user];
            if (rewardsDepot != address(0)) {
                // claim rewards to user's rewardsDepot
                uniswapV3Staker.claimReward(rewardsDepot, pendingRewards);
            } else {
                // claim rewards to user
                uniswapV3Staker.claimReward(user, pendingRewards);
            }
        }

        // withdraw rewards from Uniswap V3 Staker
        uniswapV3Staker.withdrawToken(tokenId, user, "");
    }

    /*//////////////////////////////////////////////////////////////
                            ADMIN LOGIC
    //////////////////////////////////////////////////////////////*/

    /// @inheritdoc IBoostAggregator
    function addWhitelistedAddress(address user) external onlyOwner {
        whitelistedAddresses[user] = true;
    }

    /// @inheritdoc IBoostAggregator
    function removeWhitelistedAddress(address user) external onlyOwner {
        delete whitelistedAddresses[user];
    }

    /// @inheritdoc IBoostAggregator
    function setProtocolFee(uint256 _protocolFee) external onlyOwner {
        if (_protocolFee > DIVISIONER) revert FeeTooHigh();
        protocolFee = _protocolFee;
    }

    /// @inheritdoc IBoostAggregator
    function withdrawProtocolFees(address to) external onlyOwner {
        uniswapV3Staker.claimReward(to, protocolRewards);
        delete protocolRewards;
    }

    /// @inheritdoc IBoostAggregator
    function withdrawAllGaugeBoost(address to) external onlyOwner {
        /// @dev May run out of gas.
        hermesGaugeBoost.decrementAllGaugesAllBoost();
        address(hermesGaugeBoost).safeTransfer(to, hermesGaugeBoost.balanceOf(address(this)));
    }

    /// @inheritdoc IBoostAggregator
    function withdrawGaugeBoost(address to, uint256 amount) external onlyOwner {
        /// @dev May run out of gas.
        hermesGaugeBoost.decrementAllGaugesBoost(amount);
        hermesGaugeBoost.updateUserBoost(address(this));
        address(hermesGaugeBoost).safeTransfer(to, amount);
    }

    /// @inheritdoc IBoostAggregator
    function decrementGaugesBoostIndexed(uint256 boost, uint256 offset, uint256 num) external onlyOwner {
        hermesGaugeBoost.decrementGaugesBoostIndexed(boost, offset, num);
    }

    /*///////////////////////////////////////////////////////////////
                                MODIFIERS
    //////////////////////////////////////////////////////////////*/

    /// @dev Only whitelisted addresses
    /// @param from The address who the NFT is being transferred from
    modifier onlyWhitelisted(address from) {
        if (!whitelistedAddresses[from]) revert Unauthorized();
        _;
    }
}
"},"src/talos/factories/BoostAggregatorFactory.sol":{"content":"// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import {ERC20} from "solmate/tokens/ERC20.sol";

import {UniswapV3Staker} from "@v3-staker/UniswapV3Staker.sol";

import {BoostAggregator} from "../boost-aggregator/BoostAggregator.sol";

import {IBoostAggregatorFactory} from "../interfaces/IBoostAggregatorFactory.sol";

/// @title Boost Aggregator Factory
contract BoostAggregatorFactory is IBoostAggregatorFactory {
    /*//////////////////////////////////////////////////////////////
                    BOOST AGGREGATOR FACTORY STATE
    //////////////////////////////////////////////////////////////*/

    /// @inheritdoc IBoostAggregatorFactory
    UniswapV3Staker public immutable uniswapV3Staker;

    /// @inheritdoc IBoostAggregatorFactory
    ERC20 public immutable hermes;

    /// @inheritdoc IBoostAggregatorFactory
    BoostAggregator[] public boostAggregators;

    /// @inheritdoc IBoostAggregatorFactory
    mapping(BoostAggregator => uint256) public boostAggregatorIds;

    /**
     * @notice Construct a new Boost Aggregator Factory contract.
     * @param _uniswapV3Staker Uniswap V3 Staker to use.
     */
    constructor(UniswapV3Staker _uniswapV3Staker) {
        uniswapV3Staker = _uniswapV3Staker;
        hermes = ERC20(_uniswapV3Staker.hermes());

        boostAggregators.push(BoostAggregator(address(0)));
    }

    /// @inheritdoc IBoostAggregatorFactory
    function getBoostAggregators() external view returns (BoostAggregator[] memory) {
        return boostAggregators;
    }

    /*//////////////////////////////////////////////////////////////
                            CREATE LOGIC
    //////////////////////////////////////////////////////////////*/

    /// @inheritdoc IBoostAggregatorFactory
    function createBoostAggregator(address owner) external {
        if (owner == address(0)) revert InvalidOwner();
        BoostAggregator boostAggregator = new BoostAggregator(uniswapV3Staker, hermes, owner);

        boostAggregatorIds[boostAggregator] = boostAggregators.length;
        boostAggregators.push(boostAggregator);
    }
}
